class WeatherSystem:
    CELSIUS = 'celsius'
    FAHRENHEIT = 'fahrenheit'

    def __init__(self, city) -> None:
        self._temperature = None
        self._weather = None
        self.city = city
        self._weather_list = {}

    def query(self, weather_list, tmp_units=CELSIUS):
        self._weather_list = weather_list
        if self.city not in weather_list:
            return False

        self._temperature = self.weather_list[self.city]['temperature']
        self._weather = self.weather_list[self.city]['weather']

        if self.weather_list[self.city]['temperature units'] != tmp_units:
            if tmp_units == CELSIUS:
                return self._fahrenheit_to_celsius(), self._weather
            elif tmp_units == FAHRENHEIT:
                return self._celsius_to_fahrenheit(), self._weather
        else:
            return self._temperature, self._weather

    def set_city(self, city):
        self.city = city

    def _celsius_to_fahrenheit(self):
        return (self._temperature * 9 / 5) + 32

    def _fahrenheit_to_celsius(self):
        return (self._temperature - 32) * 5 / 9

    @property
    def weather_list(self):
        return self._weather_list

    @property
    def temperature(self):
        return self._temperature

    @property
    def weather(self):
        return self._weather
